import collections
def load_tris(path):
    v=[]
    for line in open(path):
        if line.lstrip().startswith("vertex"):
            v.append([float(t) for t in line.split()[1:]])
    return np.array(v).reshape(-1,3,3)
T = np.vstack([load_tris(f"constant/triSurface/{n}.stl") for n in names])
